package com.aoo.bcg.common.cache;import java.time.Duration;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RemainingTtlPolicyTest{@Test void preservesPositiveTtlCapsPersistentAndNeverExtends(){var policy=new RemainingTtlPolicy(Duration.ofHours(1));assertEquals(Duration.ofMillis(1234),policy.fromPttlMillis(1234));assertEquals(Duration.ofHours(1),policy.fromPttlMillis(-1));assertEquals(Duration.ofSeconds(30),policy.bounded(Duration.ofMinutes(2),Duration.ofSeconds(30)));assertThrows(IllegalStateException.class,()->policy.fromPttlMillis(-2));assertThrows(IllegalStateException.class,()->policy.fromPttlMillis(0));}}
